+//! SGLang's chat layer around a template without an SGLang request path
+//! (Jinja, Dynamo's encoders, legacy conversations): the kwargs
+//! `_process_messages` hands the template and `_handle_last_assistant_message`.
+
+use std::collections::HashMap;
+
+use dynamo_protocols::types::{ChatCompletionRequestMessage, CreateChatCompletionRequest};
+use dynamo_renderer::{OAIChatLikeRequest, RenderedPrompt, TextInput};
+use serde_json::Value;
+
+use super::{ChatFormatter, TemplateError, requested_effort, requested_thinking};
+
+/// What SGLang's chat layer reads off a raw chat body for its template.
+#[derive(Debug, Clone, Default)]
+pub struct TemplateArgs {
+    kwargs: HashMap<String, Value>,
+    continuing: bool,
+}
+
+impl TemplateArgs {
+    /// Python's template kwargs: the server `defaults`, under the thinking
+    /// toggle the request's effort implies (`ChatCompletionRequest`'s
+    /// validator), under the request's own `chat_template_kwargs`. Its
+    /// `reasoning_effort` moves onto the request's
+    /// (`_convert_to_internal_request`), which the template sees unless a
+    /// default names one.
+    pub fn new(body: &Value, defaults: &HashMap<String, Value>) -> Self {
+        let mut kwargs = defaults.clone();
+        if let Some(thinking) = requested_thinking(body) {
+            kwargs.insert("thinking".into(), thinking.into());
+            kwargs.insert("enable_thinking".into(), thinking.into());
+        }
+        let mut own = body["chat_template_kwargs"]
+            .as_object()
+            .cloned()
+            .unwrap_or_default();
+        let effort = own
+            .remove("reasoning_effort")
+            .or_else(|| requested_effort(body).cloned());
+        kwargs.extend(own);
+        if let Some(effort) = effort {
+            kwargs.entry("reasoning_effort".into()).or_insert(effort);
+        }
+        Self {
+            kwargs,
+            continuing: body["continue_final_message"] == true,
+        }
+    }
+}
+
+impl ChatFormatter {
+    /// Render `request` through the formatter's own template as SGLang's chat
+    /// layer does, returning the prompt and the `continue_final_message` text
+    /// apart from it.
+    pub fn render_template(
+        &self,
+        request: &CreateChatCompletionRequest,
+        args: &TemplateArgs,
+    ) -> Result<(RenderedPrompt, String), TemplateError> {
+        let (messages, continuation) = match self {
+            ChatFormatter::Legacy(_) => None,
+            _ => last_assistant_message(request, args.continuing),
+        }
+        .map_or((None, String::new()), |(messages, prefix)| {
+            (Some(messages), prefix)
+        });
+        let request = TemplateRequest {
+            request,
+            kwargs: (!args.kwargs.is_empty()).then_some(&args.kwargs),
+            messages,
+        };
+        Ok((self.render_prompt(&request)?, continuation))
+    }
+}
+
+/// Python's `_handle_last_assistant_message`: a trailing assistant message's
+/// text is the continuation under `continue_final_message`, else a user turn.
+/// The messages to render and the continuation, if the last one is such.
+fn last_assistant_message(
+    request: &CreateChatCompletionRequest,
+    continuing: bool,
+) -> Option<(minijinja::Value, String)> {
+    if !matches!(
+        request.messages.last(),
+        Some(ChatCompletionRequestMessage::Assistant(_))
+    ) {
+        return None;
+    }
+    let mut messages = serde_json::to_value(&request.messages).ok()?;
+    let list = messages.as_array_mut()?;
+    // `_process_messages` first sets a null content to "".
+    let content = match &list.last()?["content"] {
+        Value::Null => String::new(),
+        content => content.as_str()?.to_owned(),
+    };
+    let prefix = if continuing {
+        list.pop();
+        content
+    } else {
+        *list.last_mut()? = serde_json::json!({"role": "user", "content": content});
+        String::new()
+    };
+    Some((minijinja::Value::from_serialize(&messages), prefix))
+}
+
+/// The wire request plus its `chat_template_kwargs`, which the protocol type
+/// does not carry, and the messages to render in place of its own.
+struct TemplateRequest<'a> {
+    request: &'a CreateChatCompletionRequest,
+    kwargs: Option<&'a HashMap<String, Value>>,
+    messages: Option<minijinja::Value>,
+}
+
+impl OAIChatLikeRequest for TemplateRequest<'_> {
+    fn model(&self) -> String {
+        self.request.model()
+    }
+    fn messages(&self) -> minijinja::Value {
+        match &self.messages {
+            Some(messages) => messages.clone(),
+            None => self.request.messages(),
+        }
+    }
+    fn typed_messages(&self) -> Option<&[ChatCompletionRequestMessage]> {
+        match self.messages {
+            Some(_) => None,
+            None => self.request.typed_messages(),
+        }
+    }
+    fn tools(&self) -> Option<minijinja::Value> {
+        self.request.tools()
+    }
+    fn tool_choice(&self) -> Option<minijinja::Value> {
+        self.request.tool_choice()
+    }
+    fn response_format(&self) -> Option<minijinja::Value> {
+        self.request.response_format()
+    }
+    fn reasoning_effort(&self) -> Option<minijinja::Value> {
+        self.request.reasoning_effort()
+    }
+    fn should_add_generation_prompt(&self) -> bool {
+        self.request.should_add_generation_prompt()
+    }
+    fn chat_template_args(&self) -> Option<&HashMap<String, Value>> {
+        self.kwargs
+    }
+    fn extract_text(&self) -> Option<TextInput> {
+        self.request.extract_text()
+    }
+    fn mm_processor_kwargs(&self) -> Option<&Value> {
+        self.request.mm_processor_kwargs()
+    }
+}
